    93  static JSValue promise_reaction_job(JSContext *ctx, int argc,
    94                                      JSValueConst *argv)
    95  {
    96      JSValueConst handler, arg, func;
    97      JSValue res, res2;
    98      BOOL is_reject;
    99
   100      assert(argc == 5);
   101      handler = argv[2];
   102      is_reject = JS_ToBool(ctx, argv[3]);
   103      arg = argv[4];
   104  #ifdef DUMP_PROMISE
   105      printf("promise_reaction_job: is_reject=%d\n", is_reject);
   106  #endif
   107
   108      if (JS_IsUndefined(handler)) {
   109          if (is_reject) {
   110              res = JS_Throw(ctx, JS_DupValue(ctx, arg));
   111          } else {
   112              res = JS_DupValue(ctx, arg);
   113          }
   114      } else {
   115          res = JS_Call(ctx, handler, JS_UNDEFINED, 1, &arg);
   116      }
   117      is_reject = JS_IsException(res);
   118      if (is_reject)
   119          res = JS_GetException(ctx);
   120      func = argv[is_reject];
   121      /* as an extension, we support undefined as value to avoid
   122         creating a dummy promise in the 'await' implementation of async
   123         functions */
   124      if (!JS_IsUndefined(func)) {
   125          res2 = JS_Call(ctx, func, JS_UNDEFINED,
   126                         1, (JSValueConst *)&res);
   127      } else {
   128          res2 = JS_UNDEFINED;
   129      }
   130      JS_FreeValue(ctx, res);
   131
   132      return res2;
   133  }
