   143  static void fulfill_or_reject_promise(JSContext *ctx, JSValueConst promise,
   144                                        JSValueConst value, BOOL is_reject)
   145  {
   146      JSPromiseData *s = JS_GetOpaque(promise, JS_CLASS_PROMISE);
   147      struct list_head *el, *el1;
   148      JSPromiseReactionData *rd;
   149      JSValueConst args[5];
   150
   151      if (!s || s->promise_state != JS_PROMISE_PENDING)
   152          return; /* should never happen */
   153      set_value(ctx, &s->promise_result, JS_DupValue(ctx, value));
   154      s->promise_state = JS_PROMISE_FULFILLED + is_reject;
   155  #ifdef DUMP_PROMISE
   156      printf("fulfill_or_reject_promise: is_reject=%d\n", is_reject);
   157  #endif
   158      if (s->promise_state == JS_PROMISE_REJECTED && !s->is_handled) {
   159          JSRuntime *rt = ctx->rt;
   160          if (rt->host_promise_rejection_tracker) {
   161              rt->host_promise_rejection_tracker(ctx, promise, value, FALSE,
   162                                                 rt->host_promise_rejection_tracker_opaque);
   163          }
   164      }
   165
   166      list_for_each_safe(el, el1, &s->promise_reactions[is_reject]) {
   167          rd = list_entry(el, JSPromiseReactionData, link);
   168          args[0] = rd->resolving_funcs[0];
   169          args[1] = rd->resolving_funcs[1];
   170          args[2] = rd->handler;
   171          args[3] = JS_NewBool(ctx, is_reject);
   172          args[4] = value;
   173          JS_EnqueueJob(ctx, promise_reaction_job, 5, args);
   174          list_del(&rd->link);
   175          promise_reaction_data_free(ctx->rt, rd);
   176      }
   177
   178      list_for_each_safe(el, el1, &s->promise_reactions[1 - is_reject]) {
   179          rd = list_entry(el, JSPromiseReactionData, link);
   180          list_del(&rd->link);
   181          promise_reaction_data_free(ctx->rt, rd);
   182      }
   183  }
