   191  static JSValue js_promise_resolve_thenable_job(JSContext *ctx,
   192                                                 int argc, JSValueConst *argv)
   193  {
   194      JSValueConst promise, thenable, then;
   195      JSValue args[2], res;
   196
   197  #ifdef DUMP_PROMISE
   198      printf("js_promise_resolve_thenable_job\n");
   199  #endif
   200      assert(argc == 3);
   201      promise = argv[0];
   202      thenable = argv[1];
   203      then = argv[2];
   204      if (js_create_resolving_functions(ctx, args, promise) < 0)
   205          return JS_EXCEPTION;
   206      res = JS_Call(ctx, then, thenable, 2, (JSValueConst *)args);
   207      if (JS_IsException(res)) {
   208          JSValue error = JS_GetException(ctx);
   209          res = JS_Call(ctx, args[1], JS_UNDEFINED, 1, (JSValueConst *)&error);
   210          JS_FreeValue(ctx, error);
   211      }
   212      JS_FreeValue(ctx, args[0]);
   213      JS_FreeValue(ctx, args[1]);
   214      return res;
   215  }
