   225  static int js_create_resolving_functions(JSContext *ctx,
   226                                           JSValue *resolving_funcs,
   227                                           JSValueConst promise)
   228
   229  {
   230      JSValue obj;
   231      JSPromiseFunctionData *s;
   232      JSPromiseFunctionDataResolved *sr;
   233      int i, ret;
   234
   235      sr = js_malloc(ctx, sizeof(*sr));
   236      if (!sr)
   237          return -1;
   238      sr->ref_count = 1;
   239      sr->already_resolved = FALSE; /* must be shared between the two functions */
   240      ret = 0;
   241      for(i = 0; i < 2; i++) {
   242          obj = JS_NewObjectProtoClass(ctx, ctx->function_proto,
   243                                       JS_CLASS_PROMISE_RESOLVE_FUNCTION + i);
   244          if (JS_IsException(obj))
   245              goto fail;
   246          s = js_malloc(ctx, sizeof(*s));
   247          if (!s) {
   248              JS_FreeValue(ctx, obj);
   249          fail:
   250
   251              if (i != 0)
   252                  JS_FreeValue(ctx, resolving_funcs[0]);
   253              ret = -1;
   254              break;
   255          }
   256          sr->ref_count++;
   257          s->presolved = sr;
   258          s->promise = JS_DupValue(ctx, promise);
   259          JS_SetOpaque(obj, s);
   260          js_function_set_properties(ctx, obj, JS_ATOM_empty_string, 1);
